using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "SearchDiceOnPoolDrawAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/SearchDiceOnPoolDraw Action")]
public class SearchDiceOnPoolDrawAction : SearchDiceOnPoolAction
{
	[Header("SearchDiceOnPoolAction Specifics")]
	[SerializeField]
	private bool drawFromDiscard;

	public override void DiceChosen(Dice dice)
	{
		poolToChooseFrom.DecreaseDiceAmount(dice, 1);
		List<Dice> list = new List<Dice>();
		list.Add(dice);
		ReferenceSingleton<DiceDrawingHandler>.Instance.DrawSpecificDiceFromSinglePool(list, drawFromDiscard);
		OnHideSearchDiceOnPoolCanvas.Raise();
	}
}
